class Wizard {
    protected String name;
    Wizard(String n) { name = n; }
    void greet() { System.out.println("I am " + name); }
}
class FireWizard extends Wizard {
    FireWizard(String n) { super(n); }
    void castFireball() { System.out.println(name + " casts Fireball!"); }
}
FireWizard fw = new FireWizard("Ignis");
fw.greet();       // I am Ignis  (inherited)
fw.castFireball(); // Ignis casts Fireball!

